// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // We fuzz: an address 'from', a receiver address 'rec', and a uint value v,
    // plus a boolean 'makeEmpty' to ensure we can test domain with non-empty _tos.
    function testFuzz_property(address from, address rec, uint256 v, bool makeEmpty) public {
        // keep rec non-zero to be a valid contract address we will deploy
        vm.assume(rec != address(0));

        // Deploy a Recording helper that defines the exact function the reference calls:
        // function transferFrom(address from, address to, uint256 v) external returns (bool)
        Recorder r = new Recorder();

        // Build _tos: the contract expects a non-empty array. If makeEmpty is true, set length 0
        address[] memory tos;
        if (makeEmpty) {
            // empty array case: the call should revert in both ref and mutant; we restrict to non-empty
            // so skip this by bounding to non-empty domain instead
            tos = new address[](0);
        } else {
            tos = new address[](1);
            tos[0] = address(r);
        }

        // Ensure we test the admissible domain: require non-empty tos
        vm.assume(tos.length > 0);

        // Call transfer and capture whether it reverted or not. We do not send ETH.
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always performs a call with selector transferFrom(...)
        // to the callee with the decoded args; our Recorder increments callCount when that
        // function is invoked. Therefore, for ALL admissible inputs, the reference yields
        // recorder.callCount() == 1 and recorder.lastFrom() == from and recorder.lastTo() == tos[0]
        // and recorder.lastV() == v. The mutant that uses the other selector will not match
        // this function signature and recorder.callCount() can be 0 for some inputs.

        // Observe recorder's recorded values (the only external observation permitted).
        // We assert the universal property: for ALL inputs the reference would have recorded
        // exactly one matching call; this assertion will pass on the reference and fail on the mutant
        // for some fuzzed inputs (the fuzzer will find such).
        assertTrue(r.callCount() == 1 && r.lastFrom() == from && r.lastTo() == tos[0] && r.lastV() == v && ok == true);
    }
}

// Recorder exposes exactly the function the reference dispatches to, records decoded args,
// and returns a boolean to make the low-level call succeed. This makes the external behaviour
// observable to the test and distinguishes the two selectors.
contract Recorder {
    uint public callCount;
    address public lastFromAddr;
    address public lastToAddr;
    uint public lastVal;

    // match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        callCount += 1;
        lastFromAddr = from;
        lastToAddr = to;
        lastVal = v;
        return true;
    }

    // getters with the names used in test
    function lastFrom() external view returns (address) { return lastFromAddr; }
    function lastTo() external view returns (address) { return lastToAddr; }
    function lastV() external view returns (uint) { return lastVal; }
}
